"""Build the interactive benchmark explorer from saved JMH measurements."""
import html
import json
from pathlib import Path
from report import LIBRARIES, VERSIONS, COLORS, OPERATIONS

def write_explorer(source, rows, navigation, css):
    libraries=[lib for lib in LIBRARIES if any(r['params']['library']==lib for r in rows)]
    backends=json.loads((source/'backends.json').read_text())
    points=[]
    for row in rows:
        metric=row['primaryMetric']
        points.append(dict(library=row['params']['library'],size=int(row['params']['size']),operation=row['params']['operation'],mean=metric['score'],low=metric['scoreConfidence'][0],high=metric['scoreConfidence'][1],error=metric['scoreError'],forks=row['forks'],iterations=sum(map(len,metric['rawData']))))
    data=dict(run=source.name,libraries=[dict(id=lib,label=VERSIONS[lib],color=COLORS[lib],backend=backends.get(lib,'')) for lib in libraries],operations=OPERATIONS,sizes=sorted({p['size'] for p in points}),points=points)
    options=''.join(f'<option value="{lib}">{html.escape(VERSIONS[lib])}</option>' for lib in libraries)
    checks=''.join(f'<label><input type="checkbox" name="library" value="{lib}" checked><span class="swatch" style="background:{COLORS[lib]}"></span>{html.escape(VERSIONS[lib])}</label>' for lib in libraries)
    ops=''.join(f'<label><input type="checkbox" name="operation" value="{op}" checked>{op}</label>' for op in OPERATIONS)
    style='''fieldset{background:white;border:1px solid #cbd6df;border-radius:10px;margin:20px 0;padding:16px}legend{font-weight:700;font-size:1.15em}.choices{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:8px}.choices label{display:flex;align-items:center;gap:8px;padding:7px;border:1px solid #dce3e8;border-radius:6px;cursor:pointer}.choices input{width:18px;height:18px;accent-color:#126c78}.swatch{width:11px;height:11px;border-radius:50%;flex-shrink:0}.toolbar{display:flex;gap:16px;flex-wrap:wrap;align-items:end;margin:14px 0}.toolbar label{display:flex;flex-direction:column;gap:4px}button,select,input{font:inherit}button,select{padding:8px 12px}button{cursor:pointer}input[type=text]{padding:8px;width:min(100%,800px);box-sizing:border-box}section{background:white;border:1px solid #dbe2e8;border-radius:12px;padding:16px;margin:24px 0}.plot{overflow-x:auto}.plot svg{width:100%;min-width:720px;height:auto;display:block}.plot circle{cursor:help}.plot circle:focus{outline:2px solid #111}#tooltip{position:fixed;z-index:10;pointer-events:none;white-space:pre-line;max-width:min(440px,calc(100vw - 24px));background:#102a38;color:white;padding:12px 16px;border-radius:8px;box-shadow:0 4px 20px #0004;font-size:14px;line-height:1.5}#selection-status{font-weight:600}.hint{font-size:.9em;color:#435766}[hidden]{display:none!important}'''
    script=(Path(__file__).parent/'chart_controls.js').read_text()
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Interactive benchmark explorer — NM Dev</title><style>{css}{style}</style></head><body><main>{navigation}<h1>NM Dev benchmark explorer</h1><p>Compare saved measurements from {html.escape(source.name)}. Hover, tap or keyboard-focus a point for timing, uncertainty and backend details.</p><p class="hint">Lower values mean less time. Both modes use a logarithmic horizontal axis. Ratios are ratios of measured means, without confidence intervals for the ratios. Results describe the recorded shared VM and backend configurations, not universal performance rankings.</p>
<fieldset><legend>Chart settings</legend><div class="toolbar"><label>Timing display<select id="mode"><option value="relative">Relative time</option><option value="absolute">Milliseconds per operation</option></select></label><label>Reference library<select id="reference">{options}</select></label><label>Axis range<select id="axis"><option value="fixed">All benchmark data (fixed)</option><option value="visible">Fit selected results</option></select></label><button id="reset" type="button">Reset settings</button></div><p class="hint">Selections are saved in this browser. A shared link takes priority over saved settings. Hiding the reference library does not change the ratios.</p></fieldset>
<fieldset id="library-filters"><legend>Visible libraries</legend><div class="choices">{checks}</div><div class="toolbar"><button id="show-all" type="button">Show all</button><button id="hide-all" type="button">Hide all</button></div></fieldset>
<fieldset><legend>Visible operations</legend><div class="toolbar"><label>Operation group<select id="operation-group"><option value="custom">Choose individually</option><option value="all">All operations</option><option value="basic">Basic matrix operations</option><option value="decomposition">Decompositions</option><option value="systems">Determinants, inverses and solves</option></select></label><button id="all-operations" type="button">Show all operations</button><button id="no-operations" type="button">Hide all operations</button></div><div class="choices">{ops}</div></fieldset>
<div class="toolbar"><button id="share" type="button">Copy comparison link</button><button id="export-csv" type="button">Download selected CSV</button></div><label for="share-url">Comparison link</label><input type="text" id="share-url" readonly><p id="selection-status" role="status" aria-live="polite"></p><p id="action-status" role="status" aria-live="polite"></p><div id="charts"></div><p><a href="results.html">Results tables</a> · <a href="methodology.html">Methodology</a> · <a href="libraries.html">Versions and backends</a> · <a href="reproduce.html">Reproduce</a></p><p class="hint">SVG downloads contain the selected chart, labels, units and run identifier. CSV exports include original millisecond timings, confidence limits and the selected reference ratios. All calculations and exports use the saved measurements; no benchmark is run in your browser.</p></main><div id="tooltip" role="tooltip" hidden></div><script type="application/json" id="benchmark-data">{json.dumps(data,separators=(',',':')).replace('<','\\u003c')}</script><script>{script}</script></body></html>'''
